<?phpini_set('display_errors',1);error_reporting(E_ALL);$time_start = time();define("DOC_ROOT","/var/www/html/web-cron/");include DOC_ROOT."config/config.php";include DOC_ROOT."lib/Opensearch.php";// berapa hari data yang mau DISIMPAN (sisanya dihapus)$totalDate = 3;// batas waktu: data dengan datepush < $dateLog akan dihapus$dateLog = date("Y-m-d 00:00:00", strtotime('-'.$totalDate.' days'));echo "Cutoff (hapus data sebelum): ".$dateLog."<br>";// index => field acuan (sesuai mapping masing-masing)$fieldMap = array(	"network-trendsarticle" => "datepush",        // tipe date	"network-trendskeyword" => "datepush.keyword" // tipe text -> pakai sub-field keyword);//OS$opensearch = new Opensearch();$opensearch->init(OS_TBO_URL,OS_TBO_USERNAME,OS_TBO_PASSWORD,true);foreach($fieldMap as $index => $field){	// kondisi: field < cutoff	$where = array();	array_push($where, array("range" => array($field => array("lt" => $dateLog))));	$condition = array("bool" =>					array("must" =>						$where					)			);	$response = $opensearch->count_total($index, $condition);	$totalOs = 0;	if($response['status']){		$totalOs = isset($response['total']) ? $response['total'] : 0;	}	$desc = "";	if($totalOs > 0){		$response_delete = $opensearch->deleteMany($index, $condition);		$status_delete = isset($response_delete['status']) ? $response_delete['status'] : 0;		if($status_delete) $desc = "Berhasil di Hapus";	}	echo "Index ".$index." (".$field.") | Total : ".$totalOs." ".$desc."<br>";}unset($opensearch);echo '<br>Execution time in seconds: ' . (microtime(true) - $time_start) . "<br>";?>